"""Close the real-burst research campaign without opening new pixels or Git writes."""
from datetime import datetime,timezone
import json
from pathlib import Path
import re
import subprocess
import sys
from study_noise_neighbourhoods import ROOT,sha256,git


def run():
    started=datetime.now(timezone.utc);proofs=sorted((ROOT/'docs/validation/raw').glob('*rafale*bruit-v*-*.json'))
    cache={};checks=[];failures=[]
    def verify(path,digest,origin):
        p=Path(path)
        if not p.is_absolute():p=ROOT/p
        key=str(p)
        if not p.is_file():failures.append(dict(origin=origin,path=key,error='missing_file'));return
        current=cache.setdefault(key,sha256(p)) if key not in cache else cache[key]
        good=current==digest;checks.append(dict(path=key,expected_sha256=digest,actual_sha256=current,match=good,origin=origin))
        if not good:failures.append(checks[-1])
    def walk(value,origin):
        if isinstance(value,dict):
            # Only explicit filesystem contracts; ordinary SHA identity records have no file path.
            if isinstance(value.get('path'),str) and isinstance(value.get('sha256'),str):verify(value['path'],value['sha256'],origin)
            for v in value.values():walk(v,origin)
        elif isinstance(value,list):
            for v in value:walk(v,origin)
    loaded=[];decoded=set()
    for p in proofs:
        if p.name.startswith('cloture-'):continue
        data=json.loads(p.read_text(encoding='utf-8'));loaded.append(dict(path=str(p),sha256=sha256(p)))
        walk(data,p.name)
        if p.name.startswith(('extraction-native-rafale','contextes-reference-rafale')):
            decoded.update(r['index'] for r in data['records'])
    report=ROOT/'docs/validation/analyses/analyse-bruit.md';text=report.read_text(encoding='utf-8');latest=text[text.index('## 439.'):]
    links=[]
    for name in re.findall(r'\]\(\.\./raw/([^\)]+)\)',latest):
        p=ROOT/'docs/validation/raw'/name;links.append(dict(name=name,exists=p.is_file()))
        if not p.is_file():failures.append(dict(error='missing_report_link',path=str(p)))
    tests=subprocess.run([sys.executable,'-m','unittest','discover','-s','tests','-p','test_noise_burst*.py'],cwd=ROOT,capture_output=True,text=True,timeout=90)
    if tests.returncode:failures.append(dict(error='targeted_unit_tests_failed',stderr=tests.stderr))
    jobs=[]
    for folder in sorted((ROOT/'build-patch_noise/jobs').glob('real-burst-*')):
        p=folder/'status.json'
        if p.is_file():
            state=json.loads(p.read_text(encoding='utf-8'));jobs.append(state)
            if state['status']=='running':failures.append(dict(error='unfinished_job',job=folder.name))
    if not any(Path(p['path']).name.startswith('chroma-partagee-rafale-bruit-v001-') for p in loaded):failures.append(dict(error='missing_shared_chroma_result'))
    if decoded!=set(range(28)):failures.append(dict(error='unexpected_decoded_partition',indices=sorted(decoded)))
    now=datetime.now(timezone.utc);output=ROOT/'docs/validation/raw'/f'cloture-rafale-bruit-v001-{now.strftime("%Y%m%dT%H%M%SZ")}.json'
    result=dict(campaign_id='noise-real-burst-20261028-v001',schema_version=1,data_version=1,measured_at_utc=now.isoformat(),
        analyser_version='noise-real-burst-research-v001',started_at_utc=started.isoformat(),completed_at_utc=now.isoformat(),
        proofs=loaded,file_checks=checks,unique_files_checked=len(cache),report_links=links,jobs=jobs,
        unit_tests=dict(command=tests.args,exit_code=tests.returncode,stdout=tests.stdout,stderr=tests.stderr),
        production_diff_paths=git('diff','--name-only','--','src').splitlines(),failures=failures,
        protocol=dict(path='docs/validation/protocols/protocole-bruit-voisinages-adaptatifs.md',sha256=sha256(ROOT/'docs/validation/protocols/protocole-bruit-voisinages-adaptatifs.md')),
        decoded_source_indices=sorted(decoded),final_sealed_source_indices=list(range(28,42)),
        runner_sha256=sha256(Path(__file__)),runner_source=Path(__file__).read_text(encoding='utf-8'),commit=git('rev-parse','HEAD'),
        rules='Verify existing JSON/files/SHA and targeted unit tests; no new source pixel decoding, Git writes, image cleanup or final holdout opening. Failed geometry job kept, not silently removed.',
        limitations='Integrity audit is not scientific quality validation, noise calibration or product stability. Source hash does not reconstruct missing images. Data remain reference-conditioned/single burst.',
        verdict='integrity_pass' if not failures else 'integrity_fail')
    with output.open('x',encoding='utf-8') as handle:json.dump(result,handle,ensure_ascii=False,indent=1,allow_nan=False)
    print('AUDIT',output,'FAILURES',len(failures),'UNIQUE_FILES',len(cache),flush=True)
    if failures:raise SystemExit(1)


if __name__=='__main__':run()
